Rewrite the following GNU C++14 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to rewrite:
<original_code>
#include<bits/stdc++.h>

using namespace std;

typedef long long ll;
typedef unsigned long long ull;

const int N=250005,M=1<<17,D=18;

int P;
int power(int a,int t){
	int r=1;
	while(t){
		if(t&1)r=(ll)r*a%P;
		a=(ll)a*a%P;t>>=1;
	}
	return r;
}

int L,K,fac[N],n,m,bit[20],ifac[N],bitcnt[N];
ll suma[D][M],sumc[D][M];
ull dp[D][M],tmp[D][M];

int main(){

	scanf("%d%d%d",&L,&K,&P);
	fac[0]=1;
	for(int i=1;i<=L;i++){
		fac[i]=(ll)fac[i-1]*i%P;
		bitcnt[i]=bitcnt[i>>1]+(i&1);
	}
	ll all=power(K,L);
	if(L&1)printf("%lld\n",all),exit(0);

	ifac[L]=power(fac[L],P-2);
	for(int i=L;i>=1;i--)ifac[i-1]=(ll)ifac[i]*i%P;
	for(int i=1;(1<<i)<=L;i++)if(L>>i&1)bit[n++]=1<<i;

	m=1<<n;
	// build a
	for(int i=0;i<m;i++){
		int s=0;
		for(int j=0;j<n;j++)if(i>>j&1)s+=bit[j];
		suma[bitcnt[i]][i]=ifac[s];
	}

	// get suma
	for(int t=0;t<=n;t++){
		int i,j,k,l;
		ll*a=suma[t];
		for(l=m;l>=2;l>>=1)for(j=0,i=l>>1;j<m;j+=l)for(k=0;k<i;k++)a[j+k+i]+=a[j+k];
		for(j=0;j<m;j++)a[j]=a[j]%P;
	}

	for(int t=0;t<=n;t++)memcpy(dp[t],suma[t],m<<3);
	int cc=0,revK=0;
	while(K)(revK<<=1)|=K&1,cc++,K>>=1;
	for(cc--,revK>>=1;cc;cc--,revK>>=1){

		// use dp to update dp
		// f i,j means V = i, P = j
		// f (a + b),j = ∑g a,j * h b,j 

		for(int t=0;t<=n;t++)memset(tmp[t],0,m<<3);
		for(int a=0;a<=n;a++)for(int b=0;a+b<=n;b++){
			ull*f=tmp[a+b],*g=dp[a],*h=dp[b];
			for(int j=0;j<m;j++)f[j]+=g[j]*h[j];
		}
		for(int t=0;t<=n;t++)for(int j=0;j<m;j++)dp[t][j]=tmp[t][j]%P;

		if(revK&1){
			// use suma to update dp

			for(int t=0;t<=n;t++)memset(tmp[t],0,m<<3);
			for(int a=0;a<=n;a++)for(int b=0;a+b<=n;b++){
				ull*f=tmp[a+b],*g=dp[a]; ll*h=suma[b];
				for(int j=0;j<m;j++)f[j]+=g[j]*h[j];
			}
			for(int t=0;t<=n;t++)for(int j=0;j<m;j++)dp[t][j]=tmp[t][j]%P;

		}
	}

	// get answer
	for(int t=0;t<=n;t++)memcpy(sumc[t],dp[t],m<<3);
	for(int t=0;t<=n;t++){
		int i,j,k,l;
		ll*a=sumc[t];
		for(l=2;l<=m;l<<=1)for(j=0,i=l>>1;j<m;j+=l)for(k=0;k<i;k++)a[j+k+i]-=a[j+k];
		for(j=0;j<m;j++)a[j]=(a[j]%P+P)%P;
	}

	ll ans=(all-sumc[n][(1<<n)-1]*fac[L]%P+P)%P;
	printf("%lld\n",ans);

	return 0;
}
